CREATE SEQUENCE customer_seq START WITH 1 INCREMENT BY 1;

CREATE OR REPLACE TRIGGER customer_bir
BEFORE INSERT ON customers FOR EACH ROW
BEGIN
  SELECT customer_seq.NEXTVAL INTO :new.customer_id FROM dual;
END;

